package at.hausgarten.service;

import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.io.*;
import java.math.*;
import java.time.*;
import java.util.*;

/** Local invoice snapshots, document outbox and append-only payment allocations in the existing DB. */
final class LocalInvoiceService {
    private final Context context;private final PixelLocalStore store;private final java.time.Clock clock;
    LocalInvoiceService(Context context,PixelLocalStore store){this(context,store,java.time.Clock.system(ZoneId.of("Europe/Vienna")));}
    LocalInvoiceService(Context context,PixelLocalStore store,java.time.Clock clock){this.context=context;this.store=store;this.clock=clock;}
    JSONObject performIfLocal(String name,JSONObject args,String request)throws Exception {
        if(!LocalAuthorityGuard.local(context))return null;
        switch(name){
            case "request_invoice_issue":return issue(args,request);
            case "create_invoice_correction":return correction(args,request);
            case "prepare_invoice_share":return prepareShare(args);
            case "update_invoice_payment":throw new IOException("PAYMENT_AMOUNT_AND_ALLOCATION_REQUIRED");
            case "record_payment":case "correct_payment":return payment(name,args,request);
            case "retry_invoice_document_job":return retryDocument(args,request);
            default:return null;
        }
    }
    JSONObject query(String name,JSONObject args)throws Exception {
        if(name.equals("get_payment_ledger"))return ledger(args);
        if(name.equals("get_invoice_document_job")){JSONObject invoice=invoice(args.getString("invoice_id"));String raw=store.ownerValue("local_invoice_job:"+invoice.getString("id"),""),recorded=invoice.optString("pdf_state",invoice.optString("pdf_sha256").isEmpty()?"MISSING":"READY");JSONObject result=new JSONObject().put("invoice_id",invoice.getString("id")).put("record_hash",OwnerJournalRules.version(invoice)).put("recorded_pdf_state",recorded).put("pdf_state",recorded).put("original_verified",false).put("job",raw.isEmpty()?JSONObject.NULL:safeJob(new JSONObject(raw)));if(recorded.equals("READY"))try{verifiedInvoice(invoice);result.put("original_verified",true);}catch(Exception missing){result.put("pdf_state","ORIGINAL_REVIEW_REQUIRED").put("error_code","INVOICE_DOCUMENT_ORIGINAL_MISSING_OR_CHANGED");}return result;}
        throw new IllegalArgumentException("LOCAL_FINANCIAL_QUERY_UNKNOWN");
    }
    private JSONObject issue(JSONObject args,String request)throws Exception {
        LocalAuthorityGuard guard=new LocalAuthorityGuard(context);guard.requireInvoiceAuthority();SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{
            JSONObject all=materialize(),current=PixelMcpWriteTools.find(all.getJSONArray("invoices"),args.getString("invoice_id"));TestDataRules.noDelivery(current,all);
            if(IssuedInvoiceRules.isIssued(current)){
                if(request.equals(current.optString("local_issue_request"))){db.setTransactionSuccessful();return issuedResult(current).put("replayed",true);}throw new IOException("INVOICE_ALREADY_ISSUED");
            }
            if(!PixelMcpWriteTools.hash(PixelMcpEntityWriteTools.recordForHash("invoice",current)).equals(args.getString("expected_record_hash")))throw new IOException("WRITE_CONFLICT");
            JSONObject payload=new JSONObject().put("id",current.getString("id")).put("confirmed",args.optBoolean("confirmed")).put("_expected_invoice",DriveJournalRules.guard(current,"invoice")).put("_expected_settings_hash",PixelMcpWriteTools.hash(all.getJSONObject("business_settings"))).put("_expected_recipient_hash",OwnerJournalRules.version(PixelMcpWriteTools.find(all.getJSONArray("customers"),current.getString("customer_id"))));
            JSONObject expected=new JSONObject();JSONArray links=current.optJSONArray("worklog_ids");for(int i=0;links!=null&&i<links.length();i++)expected.put(links.getString(i),DriveJournalRules.guard(PixelMcpWriteTools.find(all.getJSONArray("worklogs"),links.getString(i)),"worklog"));payload.put("_expected_worklogs",expected);
            JSONObject validation=new JSONObject(all.toString());
            if("cancellation".equals(current.optString("document_type")))clearActiveSources(PixelMcpWriteTools.find(validation.getJSONArray("invoices"),current.getString("correction_of")));
            // Historical whole-source rules remain for unledgered originals. Only our verified
            // quantity ledger permits remaining quantities from previous local partial invoices.
            for(int i=0;i<validation.getJSONArray("invoices").length();i++){JSONObject other=validation.getJSONArray("invoices").getJSONObject(i);String saved=store.ownerValue("local_invoice_sources:"+other.getString("id"),"");if(!saved.isEmpty()&&IssuedInvoiceRules.isIssued(other))other.put("worklog_ids",new JSONArray());}
            JSONObject prepared=InvoiceIssueRules.prepare(validation,new JSONObject().put("payload",payload),LocalDate.now(clock));for(String field:new String[]{"pdf_sha256","pdf_storage_name","pdf_byte_size","pdf_base64","document_id","pdf_filename"})prepared.remove(field);JSONObject money=LocalAuthorityRules.exactTotals(prepared),allocations=allocateSources(prepared,all),materials=allocateMaterialSources(prepared);
            String counterRaw=store.ownerValue("local_invoice_counter","");if(counterRaw.isEmpty())throw new IOException("INVOICE_AUTHORITY_RECONCILIATION_REQUIRED");JSONObject counter=new JSONObject(counterRaw),authority=guard.current();int old=counter.getInt("last_number");
            if(old<authority.optInt("invoice_high_water"))throw new IOException("INVOICE_NUMBER_ROLLBACK_RECONCILIATION_REQUIRED");if(old>=1000000000)throw new IOException("INVOICE_NUMBER_RANGE_EXHAUSTED");
            int number=old+1;JSONObject settings=all.getJSONObject("business_settings");String format=settings.getString("invoice_number_format"),prefix=settings.optString("invoice_prefix");if(!Arrays.asList("own","sevdesk").contains(format)||format.equals("own")&&!prefix.matches("[A-Za-z][A-Za-z0-9-]{0,19}"))throw new IOException("INVOICE_NUMBER_CONFIGURATION_REQUIRED");String year=prepared.getString("invoice_date").substring(0,4),label=format.equals("sevdesk")?"RE-"+number+"/"+year:prefix+"-"+year+"-"+String.format(Locale.ROOT,"%04d",number);
            for(int i=0;i<all.getJSONArray("invoices").length();i++)if(label.equals(all.getJSONArray("invoices").getJSONObject(i).optString("invoice_number")))throw new IOException("INVOICE_NUMBER_COLLISION");String external=store.ownerValue("local_invoice_external_evidence","");if(!external.isEmpty()){JSONArray known=new JSONObject(external).getJSONArray("issued");for(int i=0;i<known.length();i++)if(label.equals(known.getJSONObject(i).getString("invoice_number")))throw new IOException("INVOICE_NUMBER_COLLISION");}
            String stamp=Instant.now(clock).toString();JSONObject issued=new JSONObject(prepared.toString()).put("invoice_number",label).put("issued_at",stamp).put("updated_at",stamp).put("status","Gestellt").put("local_issue_request",request).put("money_minor",money).put("pdf_state","PDF_PENDING").put("document_job_id","invoice:"+prepared.getString("id")).put("local_source_allocations",allocations).put("local_material_source_allocations",materials).put("numbering_receipt",new JSONObject().put("authority",LocalAuthorityRules.ENGINE).put("migration_epoch",authority.optString("migration_epoch")).put("invoice_id",prepared.getString("id")).put("invoice_number",label).put("counter",number).put("request_id",request).put("action_sha256",PixelMcpWriteTools.hash(args)));
            String frozenHash=PixelMcpWriteTools.hash(issued);JSONObject reservation=new JSONObject().put("formatVersion",1).put("request_id",request).put("invoice_id",issued.getString("id")).put("invoice_number",label).put("counter",number).put("snapshot_sha256",frozenHash).put("reserved_at",stamp);
            // Number, frozen invoice, source allocations and outbox commit together. The
            // independent device high-water checkpoint follows the outer owner transaction.
            store.putOwnerValue("local_number_reservation:"+request,reservation.toString());counter.put("last_number",number);store.putOwnerValue("local_invoice_counter",counter.toString());
            store.putOwnerValue("local_invoice_sources:"+issued.getString("id"),allocations.toString());store.putOwnerValue("local_invoice_material_sources:"+issued.getString("id"),materials.toString());store.putOwnerValue("local_invoice_job:"+issued.getString("id"),new JSONObject().put("formatVersion",1).put("invoice_id",issued.getString("id")).put("phase","PDF_PENDING").put("attempts",0).put("snapshot",issued).put("snapshot_sha256",frozenHash).toString());OwnerJournalRules.replace(all,"invoices",issued.getString("id"),issued);
            for(Iterator<String> it=allocations.keys();it.hasNext();){String id=it.next();JSONObject log=new JSONObject(PixelMcpWriteTools.find(all.getJSONArray("worklogs"),id).toString());BigDecimal available=new BigDecimal(log.get("hours").toString()),used=sourceUsed(id);if(used.compareTo(available)>=0)log.put("billed",1);OwnerJournalRules.replace(all,"worklogs",id,log);}
            if("cancellation".equals(issued.optString("document_type"))){JSONObject original=new JSONObject(PixelMcpWriteTools.find(all.getJSONArray("invoices"),issued.getString("correction_of")).toString());original.put("status","Storniert");OwnerJournalRules.replace(all,"invoices",original.getString("id"),original);}
            store.commitLocalSnapshot(all);db.setTransactionSuccessful();return issuedResult(issued);
        }finally{db.endTransaction();}
    }
    private JSONObject allocateSources(JSONObject invoice,JSONObject all)throws Exception {
        JSONObject allocations=new JSONObject();JSONArray lines=invoice.getJSONArray("positions");
        for(int i=0;i<lines.length();i++){JSONObject line=lines.getJSONObject(i);String id=line.optString("worklog_id");if(id.isEmpty())continue;JSONObject log=PixelMcpWriteTools.find(all.getJSONArray("worklogs"),id);BigDecimal quantity=new BigDecimal(line.get("quantity").toString()),available=new BigDecimal(log.get("hours").toString());String unit=line.optString("unit").toLowerCase(Locale.ROOT);if(!Arrays.asList("h","std","std.","stunde","stunden").contains(unit))throw new IOException("INVOICE_SOURCE_UNIT_REVIEW_REQUIRED");if(allocations.has(id)||quantity.signum()<=0||sourceUsed(id).add(quantity).compareTo(available)>0)throw new IOException("INVOICE_SOURCE_QUANTITY_EXCEEDED");
            for(int j=0;j<all.getJSONArray("invoices").length();j++){JSONObject old=all.getJSONArray("invoices").getJSONObject(j);if(!IssuedInvoiceRules.isIssued(old)||!store.ownerValue("local_invoice_sources:"+old.getString("id"),"").isEmpty())continue;JSONArray used=old.optJSONArray("worklog_ids");for(int k=0;used!=null&&k<used.length();k++)if(id.equals(used.getString(k)))throw new IOException("INVOICE_SOURCE_ALREADY_BILLED");}
            allocations.put(id,quantity.toPlainString());
        }return allocations;
    }
    private BigDecimal sourceUsed(String worklog)throws Exception {BigDecimal total=BigDecimal.ZERO;try(Cursor keys=store.getReadableDatabase().rawQuery("SELECT key FROM owner_state WHERE key LIKE 'local_invoice_sources:%'",null)){while(keys.moveToNext()){JSONObject allocation=new JSONObject(store.ownerValue(keys.getString(0),"{}"));if(allocation.has(worklog))total=total.add(new BigDecimal(allocation.getString(worklog)));}}return total;}
    private JSONObject allocateMaterialSources(JSONObject invoice)throws Exception {
        // A cancellation refers to the original frozen source snapshot; it does
        // not consume those physical materials or allocate their quantities again.
        if("cancellation".equals(invoice.optString("document_type")))return new JSONObject();
        JSONObject allocated=new JSONObject();JSONArray lines=invoice.getJSONArray("positions");for(int i=0;i<lines.length();i++){JSONObject line=lines.getJSONObject(i);if(!line.optString("source_type").equals("material_movement"))continue;String id=line.getString("source_id"),raw=store.ownerValue("revier:v1:entity:material_movement:"+id,"");if(raw.isEmpty())throw new IOException("INVOICE_MATERIAL_SOURCE_MISSING");JSONObject movement=new JSONObject(raw);if(!movement.optString("movement_kind").equals("consume")||!store.ownerValue("revier:v1:reversed:"+id,"").isEmpty()||allocated.has(id))throw new IOException("INVOICE_MATERIAL_SOURCE_NOT_AVAILABLE");if(!line.getString("unit").equals(movement.getString("unit")))throw new IOException("INVOICE_SOURCE_UNIT_REVIEW_REQUIRED");JSONObject canonical=SnapshotProjection.effective(store.getState());String recipient=movement.optString("billing_customer_id");if(recipient.isEmpty())recipient=BillingRules.defaultRecipient(movement.getString("customer_id"),movement.optString("order_id"),canonical);if(!invoice.getString("customer_id").equals(recipient))throw new IOException("INVOICE_MATERIAL_RECIPIENT_MISMATCH");
            BigDecimal quantity=new BigDecimal(line.optString("source_quantity_decimal",line.get("quantity").toString())),available=new BigDecimal(movement.getString("quantity_decimal")).abs(),used=BigDecimal.ZERO;if(quantity.compareTo(new BigDecimal(line.get("quantity").toString()))!=0)throw new IOException("INVOICE_SOURCE_QUANTITY_REVIEW_REQUIRED");
            try(Cursor keys=store.getReadableDatabase().rawQuery("SELECT key FROM owner_state WHERE key LIKE 'local_invoice_material_sources:%'",null)){while(keys.moveToNext()){JSONObject values=new JSONObject(store.ownerValue(keys.getString(0),"{}"));if(values.has(id))used=used.add(new BigDecimal(values.getString(id)));}}
            if(quantity.signum()<=0||used.add(quantity).compareTo(available)>0)throw new IOException("INVOICE_SOURCE_QUANTITY_EXCEEDED");allocated.put(id,quantity.toPlainString());
        }return allocated;
    }
    private static void clearActiveSources(JSONObject invoice)throws Exception {JSONArray positions=invoice.getJSONArray("positions");for(int i=0;i<positions.length();i++)for(String field:new String[]{"source_type","source_id","source_quantity_decimal"})positions.getJSONObject(i).remove(field);}
    private JSONObject correction(JSONObject args,String request)throws Exception {SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{
        JSONObject all=materialize(),original=PixelMcpWriteTools.find(all.getJSONArray("invoices"),args.getString("invoice_id"));if(!PixelMcpWriteTools.hash(PixelMcpEntityWriteTools.recordForHash("invoice",original)).equals(args.getString("expected_record_hash")))throw new IOException("WRITE_CONFLICT");
        // The original validator predates source_* position metadata. Corrections
        // refer to the immutable original; copied positions are no new allocation.
        JSONObject validation=new JSONObject(all.toString()),shadow=PixelMcpWriteTools.find(validation.getJSONArray("invoices"),original.getString("id"));clearActiveSources(shadow);
        JSONObject payload=new JSONObject(args.toString()).put("id",original.getString("id")).put("_expected_invoice",DriveJournalRules.guard(shadow,"invoice"));InvoiceIssueRules.correction(validation,new JSONObject().put("client_id",request).put("created_at",Instant.now(clock).toString()).put("payload",payload));
        String id="inv_correction_"+PixelMcpWriteTools.hash(request).substring(0,32);JSONObject draft=PixelMcpWriteTools.find(validation.getJSONArray("invoices"),id);
        for(String field:new String[]{"local_issue_request","local_source_allocations","local_material_source_allocations","document_job_id","pdf_state","payment_balance"})draft.remove(field);
        OwnerJournalRules.replace(all,"invoices",id,draft);store.commitLocalSnapshot(all);db.setTransactionSuccessful();return new JSONObject().put("correction_state","draft_created").put("invoice_id",id).put("entity_id",id).put("requires_issue_confirmation",true);
    }finally{db.endTransaction();}}
    private JSONObject prepareShare(JSONObject args)throws Exception {JSONObject all=materialize(),invoice=PixelMcpWriteTools.find(all.getJSONArray("invoices"),args.getString("invoice_id"));TestDataRules.noDelivery(invoice,all);if(!invoice.optString("pdf_state","READY").equals("READY")||invoice.optString("pdf_sha256").isEmpty())throw new IOException("INVOICE_PDF_NOT_READY");verifiedInvoice(invoice);JSONObject result=new JSONObject().put("invoice_id",invoice.getString("id")).put("channel",args.getString("channel")).put("state","device_interaction_required").put("sent",false).put("delivered",false);store.putOwnerValue("invoice_share_handoff",result.toString());return result;}
    private void verifiedInvoice(JSONObject invoice)throws Exception {
        String raw=store.ownerValue("local_invoice_job:"+invoice.getString("id"),"");
        if(raw.isEmpty())LocalInvoiceJobs.verifiedOriginal(context,invoice);else LocalInvoiceJobs.verifyReady(context,new JSONObject(raw),invoice);
    }
    private JSONObject retryDocument(JSONObject args,String request)throws Exception {JSONObject current=invoice(args.getString("invoice_id"));if(!OwnerJournalRules.version(current).equals(args.getString("expected_record_hash")))throw new IOException("WRITE_CONFLICT");String key="local_invoice_job:"+current.getString("id"),raw=store.ownerValue(key,"");if(raw.isEmpty())throw new IOException("INVOICE_DOCUMENT_JOB_MISSING");JSONObject job=new JSONObject(raw);if(job.optString("phase").equals("ORIGINAL_REVIEW_REQUIRED"))throw new IOException("INVOICE_DOCUMENT_ORIGINAL_MISSING_OR_CHANGED");if(job.optString("phase").equals("READY")){verifiedInvoice(current);return safeJob(job);}job.put("phase","PDF_PENDING").put("attempts",0);store.putOwnerValue(key,job.toString());return safeJob(job);}
    private JSONObject payment(String name,JSONObject args,String request)throws Exception {
        SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{
            JSONObject current=ledger(new JSONObject());if(!current.getString("ledger_hash").equals(args.getString("expected_ledger_hash")))throw new IOException("PAYMENT_LEDGER_WRITE_CONFLICT");JSONObject all=materialize();JSONArray entries=paymentEntries();String stamp=Instant.now(clock).toString(),id="pay_"+PixelMcpWriteTools.hash(request).substring(0,32);
            if(name.equals("correct_payment")){
                if(args.optString("reason").trim().isEmpty())throw new IOException("PAYMENT_CORRECTION_REASON_REQUIRED");JSONObject old=null;for(int i=0;i<entries.length();i++)if(entries.getJSONObject(i).getString("payment_id").equals(args.getString("payment_id")))old=entries.getJSONObject(i);if(old==null||old.optBoolean("reversal")||exactMinor(old.get("amount_minor"))<=0)throw new IOException("PAYMENT_NOT_CORRECTABLE");for(int i=0;i<entries.length();i++)if(old.getString("payment_id").equals(entries.getJSONObject(i).optString("reverses")))throw new IOException("PAYMENT_ALREADY_CORRECTED");JSONArray reversed=new JSONArray();JSONArray oldAlloc=old.getJSONArray("allocations");for(int i=0;i<oldAlloc.length();i++)reversed.put(new JSONObject(oldAlloc.getJSONObject(i).toString()).put("amount_minor",Math.negateExact(oldAlloc.getJSONObject(i).getLong("amount_minor"))));JSONObject reversal=new JSONObject().put("formatVersion",1).put("payment_id",id+"_reversal").put("amount_minor",Math.negateExact(old.getLong("amount_minor"))).put("allocations",reversed).put("reversal",true).put("reverses",old.getString("payment_id")).put("reason",args.getString("reason")).put("recorded_at",stamp);store.putOwnerValue("local_payment:"+reversal.getString("payment_id"),reversal.toString());entries.put(reversal);
            }
            long amount=exactMinor(args.get("amount_minor"));if(amount<0||amount==0&&!name.equals("correct_payment"))throw new IOException("PAYMENT_POSITIVE_AMOUNT_REQUIRED");if(amount==0&&args.getJSONArray("allocations").length()!=0)throw new IOException("PAYMENT_ZERO_CORRECTION_REQUIRES_EMPTY_ALLOCATIONS");LocalDate date=LocalDate.parse(args.getString("paid_on"));if(date.isAfter(LocalDate.now(clock)))throw new IOException("PAYMENT_DATE_IN_FUTURE");String method=args.getString("method");if(!Arrays.asList("cash","bank","card","other").contains(method))throw new IOException("PAYMENT_METHOD_INVALID");JSONArray allocations=new JSONArray(args.getJSONArray("allocations").toString());long total=0;Set<String> used=new HashSet<>();
            for(int i=0;i<allocations.length();i++){JSONObject allocation=allocations.getJSONObject(i),invoice=PixelMcpWriteTools.find(all.getJSONArray("invoices"),allocation.getString("invoice_id"));if(!used.add(invoice.getString("id"))||!IssuedInvoiceRules.isIssued(invoice)||invoice.optString("status").equals("Storniert"))throw new IOException("PAYMENT_INVOICE_INVALID");if(!OwnerJournalRules.version(invoice).equals(allocation.getString("expected_record_hash")))throw new IOException("WRITE_CONFLICT");JSONObject known=balance(invoice,entries);if(!known.getBoolean("balance_known"))throw new IOException("PAYMENT_BALANCE_RECONCILIATION_REQUIRED");if(known.getLong("invoice_minor")<=0)throw new IOException("PAYMENT_CREDIT_DOCUMENT_ALLOCATION_REQUIRES_REVIEW");long assigned=exactMinor(allocation.get("amount_minor"));if(assigned<=0)throw new IOException("PAYMENT_ALLOCATION_INVALID");try{total=Math.addExact(total,assigned);}catch(ArithmeticException invalid){throw new IOException("PAYMENT_AMOUNT_MINOR_INVALID");}allocation.remove("expected_record_hash");}
            if(total>amount)throw new IOException("PAYMENT_ALLOCATION_EXCEEDS_AMOUNT");JSONObject payment=new JSONObject().put("formatVersion",1).put("payment_id",id).put("request_id",request).put("client_request_id",args.getString("request_id")).put("amount_minor",amount).put("unallocated_minor",amount-total).put("paid_on",date.toString()).put("method",method).put("reference",args.optString("reference")).put("allocations",allocations).put("recorded_at",stamp);if(name.equals("correct_payment"))payment.put("corrects",args.getString("payment_id")).put("reason",args.getString("reason"));store.putOwnerValue("local_payment:"+id,payment.toString());entries.put(payment);
            for(int i=0;i<all.getJSONArray("invoices").length();i++){JSONObject invoice=all.getJSONArray("invoices").getJSONObject(i);JSONObject balance=balance(invoice,entries);if(balance.getBoolean("has_ledger_entries")&&!invoice.optString("status").equals("Storniert"))invoice.put("payment_balance",balance).put("status",balance.getBoolean("paid")?"Bezahlt":"Gestellt");}
            store.commitLocalSnapshot(all);db.setTransactionSuccessful();return new JSONObject().put("payment_id",id).put("local_state","local_saved").put("ledger_hash",ledger(new JSONObject()).getString("ledger_hash"));
        }finally{db.endTransaction();}
    }
    private JSONObject ledger(JSONObject args)throws Exception {JSONArray entries=paymentEntries(),filtered=new JSONArray(),balances=new JSONArray();Map<String,JSONObject> paymentIndex=new HashMap<>();for(int i=0;i<entries.length();i++)paymentIndex.put(entries.getJSONObject(i).getString("payment_id"),entries.getJSONObject(i));String invoiceId=args.optString("invoice_id");int offset=args.optInt("offset",0),limit=args.optInt("limit",50),total=0;for(int i=0;i<entries.length();i++){JSONObject p=entries.getJSONObject(i);boolean match=invoiceId.isEmpty()||paymentReferencesInvoice(p,invoiceId,paymentIndex);if(match&&total++>=offset&&filtered.length()<limit)filtered.put(p);}JSONObject state=SnapshotProjection.effective(store.getState());for(int i=0;i<state.getJSONArray("invoices").length();i++){JSONObject invoice=state.getJSONArray("invoices").getJSONObject(i);if(IssuedInvoiceRules.isIssued(invoice)&&(invoiceId.isEmpty()||invoiceId.equals(invoice.getString("id"))))balances.put(balance(invoice,entries).put("invoice_id",invoice.getString("id")).put("record_hash",OwnerJournalRules.version(invoice)));}return new JSONObject().put("formatVersion",1).put("ledger_hash",PixelMcpWriteTools.hash(entries)).put("payments",filtered).put("total",total).put("balances",balances);}
    private static boolean paymentReferencesInvoice(JSONObject payment,String invoiceId,Map<String,JSONObject> entries)throws Exception {Set<String> visited=new HashSet<>();for(JSONObject current=payment;current!=null&&visited.add(current.getString("payment_id"));){JSONArray allocations=current.getJSONArray("allocations");for(int i=0;i<allocations.length();i++)if(invoiceId.equals(allocations.getJSONObject(i).getString("invoice_id")))return true;current=entries.get(current.optString("corrects",current.optString("reverses")));}return false;}
    private JSONObject balance(JSONObject invoice,JSONArray entries)throws Exception {JSONArray amounts=new JSONArray();boolean has=false;for(int i=0;i<entries.length();i++){JSONObject p=entries.getJSONObject(i),alloc;JSONArray list=p.getJSONArray("allocations");for(int j=0;j<list.length();j++){alloc=list.getJSONObject(j);if(invoice.getString("id").equals(alloc.getString("invoice_id"))){has=true;amounts.put(new JSONObject().put("payment_id",p.getString("payment_id")).put("allocated_minor",alloc.getLong("amount_minor")));}}}long original=invoice.optJSONObject("money_minor")!=null?invoice.getJSONObject("money_minor").getLong("gross_minor"):LocalAuthorityRules.minor(invoice.has("gross_total")?invoice.get("gross_total"):invoice.get("amount"));String opening=store.ownerValue("invoice_opening_balance:"+invoice.getString("id"),"");if(!opening.isEmpty()){long baseline=new JSONObject(opening).getLong("remaining_minor");amounts.put(new JSONObject().put("payment_id","opening_baseline").put("allocated_minor",original-baseline));}JSONObject result=LocalAuthorityRules.paymentBalance(original,amounts).put("has_ledger_entries",has).put("legacy_status",invoice.optString("status")).put("balance_known",invoice.has("money_minor")||has||!invoice.optString("status").equals("Bezahlt")||!opening.isEmpty());if(!result.getBoolean("balance_known"))result.put("paid",true).put("remaining_minor",JSONObject.NULL);return result;}
    private JSONArray paymentEntries()throws Exception {JSONArray out=new JSONArray();try(Cursor rows=store.getReadableDatabase().rawQuery("SELECT key FROM owner_state WHERE key LIKE 'local_payment:%' ORDER BY rowid",null)){while(rows.moveToNext())out.put(new JSONObject(store.ownerValue(rows.getString(0),"{}")));}return out;}
    private static long exactMinor(Object value)throws IOException {try{return new BigDecimal(value.toString()).longValueExact();}catch(Exception invalid){throw new IOException("PAYMENT_AMOUNT_MINOR_INVALID");}}
    private JSONObject invoice(String id)throws Exception{return PixelMcpWriteTools.find(SnapshotProjection.effective(store.getState()).getJSONArray("invoices"),id);}
    private JSONObject materialize()throws Exception {JSONObject state=store.getState(),all=new JSONObject(state.getJSONObject("master").toString());JSONArray errors=DriveJournalRules.apply(all,state.getJSONArray("pending"));if(errors.length()>0)all.put("drive_journal_errors",errors);return all;}
    private static JSONObject safeJob(JSONObject job)throws Exception{return new JSONObject().put("invoice_id",job.getString("invoice_id")).put("phase",job.getString("phase")).put("attempts",job.optInt("attempts")).put("last_error_code",job.optString("last_error_code"));}
    private static JSONObject issuedResult(JSONObject invoice)throws Exception{return new JSONObject().put("invoice_id",invoice.getString("id")).put("invoice_number",invoice.getString("invoice_number")).put("finalization","locally_issued").put("pdf_state",invoice.optString("pdf_state","PDF_PENDING")).put("pdf_release_allowed",invoice.optString("pdf_state").equals("READY")).put("sent",false).put("record_hash",OwnerJournalRules.version(invoice));}
}
